133	func buildTarGz(t *testing.T, prefix string, entries map[string]string) []byte {
134		t.Helper()
135		var buf bytes.Buffer
136		gz := gzip.NewWriter(&buf)
137		tw := tar.NewWriter(gz)
138		for name, content := range entries {
139			full := name
140			if prefix != "" {
141				full = prefix + "/" + name
142			}
143			h := &tar.Header{Name: full, Mode: 0o644, Size: int64(len(content)), Typeflag: tar.TypeReg}
144			if err := tw.WriteHeader(h); err != nil {
145				t.Fatal(err)
146			}
147			if _, err := tw.Write([]byte(content)); err != nil {
148				t.Fatal(err)
149			}
150		}
151		if err := tw.Close(); err != nil {
152			t.Fatal(err)
153		}
154		if err := gz.Close(); err != nil {
155			t.Fatal(err)
156		}
157		return buf.Bytes()
158	}
