package deploy

// Temporary verification harness for the local blueprints working tree.
// Not meant to be committed — delete after use.

import (
	"bytes"
	"context"
	"io/fs"
	"os"
	"path/filepath"
	"testing"

	"github.com/integrio-intropy/intropy-cli/internal/blueprint"
)

const realBlueprintsRepo = "/Users/robinhultman/dev/intropy/blueprints"

func loadRealBlueprint(t *testing.T, name string) map[string]string {
	t.Helper()
	files := map[string]string{}
	root := filepath.Join(realBlueprintsRepo, name)
	err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return err
		}
		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		rel, err := filepath.Rel(realBlueprintsRepo, path)
		if err != nil {
			return err
		}
		files[filepath.ToSlash(rel)] = string(data)
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	return files
}

func renderReal(t *testing.T, bpName string, scaffoldValues map[string]any, outDir string) {
	t.Helper()
	tarball := buildTarGz(t, "owner-repo-abc123", loadRealBlueprint(t, bpName))
	srv := newRawTarballServer(t, "v0.2.0", tarball)
	defer srv.Close()

	root := t.TempDir()
	if err := blueprint.WriteScaffold(root, blueprint.Scaffold{
		SchemaVersion: blueprint.ScaffoldSchemaVersion,
		Blueprint:     bpName,
		Owner:         "o",
		Repo:          "r",
		Version:       "v0.2.0",
		Values:        scaffoldValues,
	}); err != nil {
		t.Fatal(err)
	}

	opts := CreateOptions{
		StartDir:      root,
		OutputDir:     outDir,
		NoInput:       true, // must render zero-prompt with no -f/--set
		Force:         true,
		Stderr:        &bytes.Buffer{},
		HTTP:          srv.Client(),
		GitHubBaseURL: srv.URL,
	}
	if err := Create(context.Background(), opts); err != nil {
		t.Fatalf("Create(%s): %v", bpName, err)
	}
}

func newRawTarballServer(t *testing.T, tag string, tarball []byte) *httptestServer {
	return newTarballServer(t, tag, tarball)
}

func TestVerifyRealTransactional(t *testing.T) {
	out := os.Getenv("VERIFY_OUT")
	if out == "" {
		t.Skip("set VERIFY_OUT")
	}
	// Values as int create leaves them for examples/full.yaml
	// (name: OrderSync, organization: Fluxia) plus derived appId.
	renderReal(t, "transactional", map[string]any{
		"name":         "OrderSync",
		"organization": "Fluxia",
		"empty":        false,
		"appId":        "order-sync",
	}, filepath.Join(out, "transactional"))
}

func TestVerifyRealHelloWorld(t *testing.T) {
	out := os.Getenv("VERIFY_OUT")
	if out == "" {
		t.Skip("set VERIFY_OUT")
	}
	renderReal(t, "hello-world", map[string]any{
		"name":  "HelloOrders",
		"appId": "hello-orders",
	}, filepath.Join(out, "hello-world"))
}

