// TestVerifyDottedNameAppID checks that the appId derived by the root
// template for a dotted PascalCase name satisfies the manifest template's
// appId pattern, exercising the real ResolveLayered path for both.
func TestVerifyDottedNameAppID(t *testing.T) {
	if os.Getenv("VERIFY_OUT") == "" {
		t.Skip("set VERIFY_OUT")
	}
	rootTmpl, err := blueprint.LoadTemplate(filepath.Join(realBlueprintsRepo, "transactional", "template.yaml"))
	if err != nil {
		t.Fatal(err)
	}
	values, err := blueprint.ResolveLayered(rootTmpl, nil, nil, nil,
		map[string]any{"name": "Int1055.OrderSync", "organization": "Fluxia"}, nil)
	if err != nil {
		t.Fatal(err)
	}
	appID, _ := values["appId"].(string)
	t.Logf("derived appId = %q", appID)

	manifestTmpl, err := blueprint.LoadTemplate(filepath.Join(realBlueprintsRepo, "transactional", "manifests", "template.yaml"))
	if err != nil {
		t.Fatal(err)
	}
	if _, err := blueprint.ResolveLayered(manifestTmpl,
		map[string]any{"appId": appID}, nil, nil, nil, nil); err != nil {
		t.Fatalf("derived appId %q rejected by manifest schema: %v", appID, err)
	}
}

